CREATE TRIGGER `commerce_revision_products_update` AFTER UPDATE ON `products` WHEN NEW.title IS NOT OLD.title OR NEW.slug IS NOT OLD.slug OR NEW.description IS NOT OLD.description OR NEW.status IS NOT OLD.status OR NEW.seo_title IS NOT OLD.seo_title OR NEW.seo_description IS NOT OLD.seo_description OR NEW.canonical_url IS NOT OLD.canonical_url OR NEW.og_image_key IS NOT OLD.og_image_key OR NEW.tax_code IS NOT OLD.tax_code BEGIN UPDATE settings SET value = CAST(CAST(value AS INTEGER) + 1 AS TEXT) WHERE key = 'commerce_revision'; END;--> statement-breakpoint
