CREATE TRIGGER `catalog_work_products_update` AFTER UPDATE ON `products` WHEN NEW.title IS NOT OLD.title OR NEW.slug IS NOT OLD.slug OR NEW.description IS NOT OLD.description OR NEW.status IS NOT OLD.status OR NEW.seo_title IS NOT OLD.seo_title OR NEW.seo_description IS NOT OLD.seo_description OR NEW.canonical_url IS NOT OLD.canonical_url OR NEW.og_image_key IS NOT OLD.og_image_key OR NEW.tax_code IS NOT OLD.tax_code BEGIN INSERT INTO catalog_work (id, entity_type, entity_id, target_revision, processed_revision, created_at, updated_at) VALUES ('product:' || NEW.id, 'product', NEW.id, 1, 0, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(entity_type, entity_id) DO UPDATE SET target_revision = target_revision + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'); END;
